/**
 * What the support screens need from your server. Implement it with your API layer
 * (oRPC, tRPC, route handlers, server actions) calling the support service.
 * Dates may arrive as Date or ISO strings; the screens accept both.
 */

export type DateLike = Date | string;
export type TicketStatus = "open" | "waiting" | "solved" | "spam";
export type DeliveryStatus = "queued" | "sent" | "delivered" | "read" | "failed";
export type Identity = { kind: string; value: string };
export type Agent = { id: string; name: string };
export type Customer = { id: string; name: string };
export type FileInfo = { id: string; filename: string; contentType: string; size: number };
export type Address = { address: string; name?: string | null };
/** One line about a customer's account, from your directory's `describeCustomer`. */
export type AccountFact = { label: string; value: string; url?: string | null };
export type Urgency = "urgent" | "high" | "normal" | "low";
export type Mood = "calm" | "confused" | "frustrated" | "angry";

/** What AI understood of the customer's latest message. */
export type TicketInsight = {
  topic: string | null;
  urgency: Urgency | null;
  urgencyReason: string | null;
  mood: Mood | null;
  /** BCP-47: the language the customer writes in. */
  language: string | null;
  summary: string | null;
};

export type SuggestionSource = { type: "knowledge" | "fact" | "guidance"; id: string; title: string; url?: string | null };

/** A suggested reply, or why there isn't one. */
export type Suggestion = {
  id: string;
  kind: "draft" | "cannot_answer";
  text: string | null;
  reason: string | null;
  sources: SuggestionSource[];
};

export type TicketListItem = {
  id: string;
  number: number;
  subject: string | null;
  status: TicketStatus;
  waitingSince: DateLike | null;
  lastMessageAt: DateLike;
  preview: string | null;
  previewKind: "inbound" | "outbound" | null;
  previewAuthorId: string | null;
  contact: { id: string; name: string | null; identities: Identity[] };
  customer: Customer | null;
  assignee: Agent | null;
  unread: boolean;
  /** With AI: how urgent it is, a one-line summary, and whether a suggested reply is waiting. */
  urgency?: Urgency | null;
  summary?: string | null;
  draftReady?: boolean;
};

export type TicketCounts = Record<TicketStatus, number> & { unassigned: number; mine: number };

export type TimelineMessage = {
  id: string;
  kind: "inbound" | "outbound" | "note";
  authorId: string | null;
  from: Address | null;
  to: Address[];
  cc: Address[];
  text: string;
  fullText: string | null;
  html: string | null;
  deliveryStatus: DeliveryStatus | null;
  deliveryError: string | null;
  auto: boolean;
  source: "channel" | "portal" | "agent" | "api";
  createdAt: DateLike;
  attachments: FileInfo[];
};

export type TimelineEvent = {
  id: string;
  type: "created" | "assigned" | "status_changed" | "customer_linked" | "reopened" | "follow_up" | "contact_changed" | "forwarded" | "insight_changed";
  actorId: string | null;
  data: Record<string, unknown>;
  createdAt: DateLike;
};

export type TicketDetail = {
  ticket: {
    id: string;
    number: number;
    subject: string | null;
    status: TicketStatus;
    customerId: string | null;
    assigneeId: string | null;
    waitingSince: DateLike | null;
    createdAt: DateLike;
  };
  contact: { id: string; name: string | null; identities: Identity[]; customerId: string | null; locale: string | null };
  customer: Customer | null;
  assignee: Agent | null;
  timeline: ({ type: "message"; at: DateLike; message: TimelineMessage } | { type: "event"; at: DateLike; event: TimelineEvent })[];
  channel: {
    id: string;
    kind: "email" | "sms" | "whatsapp" | "telegram" | "api";
    address: string;
    capabilities: { attachments: { maxBytes: number; maxCount: number } | false; maxTextLength: number | null };
  } | null;
  replyBlockedReason: "reply_window_closed" | "no_channel" | "no_recipient" | null;
  /** Who a reply goes to by default; agents can change who's copied. */
  recipients: { to: Address | null; cc: Address[] };
  previousTickets: { id: string; number: number; subject: string | null; status: TicketStatus; lastMessageAt: DateLike }[];
  /** Shown in the sidebar, with or without AI. */
  accountFacts?: AccountFact[];
  insight?: TicketInsight | null;
  /** The suggested reply nobody has used or discarded yet. */
  suggestion?: Suggestion | null;
};

export type ListQuery = {
  status: TicketStatus;
  /** "me", an agent id, null for unassigned, undefined for anyone. */
  assignee?: string | null;
  search?: string;
  /** Sent for open tickets when `ai` is set: most urgent first, then longest waiting. */
  sort?: "priority";
  page: number;
  pageSize: number;
};

export type RefineInstruction = "shorter" | "friendlier" | "formal" | "translate" | { custom: string };

export type AiSettings = {
  guidance: string;
  topics: string[];
  draftOnArrival: boolean;
  /** Your knowledge sources, from `ai.listKnowledgeSources()`. */
  sources: { id: string; articles: number; syncedAt: DateLike | null }[];
};

/**
 * The AI methods, each calling `support.ai` on your server. Leave `ai` off the client and the
 * screens show no AI at all.
 */
export interface SupportAiClient {
  refine(input: { ticketId: string; text: string; instruction: RefineInstruction; language?: string }): Promise<{ text: string }>;
  writeUp(input: { ticketId: string; notes: string }): Promise<{ text: string }>;
  translate(input: { messageId: string; to: string }): Promise<{ text: string }>;
  /** Asks for a suggested reply now. */
  draft(input: { ticketId: string }): Promise<unknown>;
  discardSuggestion(input: { id: string }): Promise<unknown>;
  setInsight(input: { ticketId: string; topic?: string; urgency?: Urgency }): Promise<unknown>;
  getSettings(): Promise<AiSettings>;
  updateSettings(input: Partial<Pick<AiSettings, "guidance" | "topics" | "draftOnArrival">>): Promise<unknown>;
  syncKnowledge(): Promise<unknown>;
}

export interface SupportClient {
  listTickets(query: ListQuery): Promise<{ items: TicketListItem[]; total: number }>;
  counts(): Promise<TicketCounts>;
  getTicket(id: string): Promise<TicketDetail>;
  /** `cc` is only passed when the agent changed who's copied. */
  reply(input: {
    ticketId: string;
    text: string;
    attachmentIds: string[];
    status: "waiting" | "solved" | "open";
    cc?: Address[];
    /** The suggested reply the text started from, so its outcome is recorded. */
    suggestionId?: string;
  }): Promise<unknown>;
  addNote(input: { ticketId: string; text: string; attachmentIds: string[] }): Promise<unknown>;
  assign(input: { ticketId: string; assigneeId: string | null }): Promise<unknown>;
  setStatus(input: { ticketId: string; status: TicketStatus }): Promise<unknown>;
  linkCustomer(input: { ticketId: string; customerId: string | null }): Promise<unknown>;
  changeContact(input: { ticketId: string; address: string }): Promise<unknown>;
  retry(input: { messageId: string }): Promise<unknown>;
  upload(input: { ticketId: string; file: File }): Promise<FileInfo>;
  attachmentUrl(input: { id: string }): Promise<string>;
  listAgents(): Promise<Agent[]>;
  searchCustomers(query: string): Promise<Customer[]>;
  ai?: SupportAiClient;
}

export type PortalTicket = {
  id: string;
  subject: string | null;
  status: TicketStatus;
  createdAt: DateLike;
  lastMessageAt: DateLike;
  preview: string | null;
  previewKind: "inbound" | "outbound" | null;
  previewAuthor: string | null;
  unread: boolean;
};

export type PortalMessage = {
  id: string;
  kind: "inbound" | "outbound";
  author: string | null;
  text: string;
  createdAt: DateLike;
  attachments: FileInfo[];
};

export interface SupportPortalClient {
  list(): Promise<{ items: PortalTicket[]; total: number }>;
  get(id: string): Promise<{ ticket: { id: string; subject: string | null; status: TicketStatus; createdAt: DateLike }; messages: PortalMessage[] }>;
  create(input: { subject: string; text: string }): Promise<{ id: string }>;
  reply(input: { ticketId: string; text: string }): Promise<unknown>;
  attachmentUrl(input: { id: string }): Promise<string>;
}

"use client";

import { createContext, useContext, type ReactNode } from "react";
import type { DateLike, SupportClient, SupportPortalClient, TicketDetail } from "./client";
import en from "./messages/en.json";

type Values = Record<string, string | number>;
export type Translate = (key: string, values?: Values) => string;

/** English defaults, for apps without an i18n library. With next-intl, pass useTranslations("support"). */
export function createTranslator(messages: Record<string, unknown> = en): Translate {
  return (key, values) => {
    const template = key.split(".").reduce<unknown>((node, part) => (node as Record<string, unknown> | undefined)?.[part], messages);
    if (typeof template !== "string") return key;
    return template.replace(/\{(\w+)\}/g, (_, name: string) => String(values?.[name] ?? `{${name}}`));
  };
}

type SupportContextValue = {
  client: SupportClient;
  t: Translate;
  locale: string;
  /** The signed-in agent. */
  viewerId: string;
  ticketHref: (id: string) => string;
  inboxHref: string;
  /** Your product's view of the customer next to a ticket: their account, orders, payments… */
  customerPanel?: (detail: TicketDetail) => ReactNode;
  /** Minutes a customer may wait before "Waiting" turns red. Amber from three quarters of it. */
  responseTargetMinutes: number;
};

const SupportContext = createContext<SupportContextValue | null>(null);

export function SupportProvider({
  children,
  t = createTranslator(),
  locale = "en",
  responseTargetMinutes = 240,
  ...value
}: Omit<SupportContextValue, "t" | "locale" | "responseTargetMinutes"> & {
  t?: Translate;
  locale?: string;
  responseTargetMinutes?: number;
  children: ReactNode;
}) {
  return (
    <SupportContext.Provider value={{ ...value, t, locale, responseTargetMinutes }}>{children}</SupportContext.Provider>
  );
}

export function useSupport() {
  const value = useContext(SupportContext);
  if (!value) throw new Error("Wrap support screens in <SupportProvider>.");
  return value;
}

type PortalContextValue = { client: SupportPortalClient; t: Translate; locale: string; requestHref: (id: string) => string; listHref: string };

const PortalContext = createContext<PortalContextValue | null>(null);

export function SupportPortalProvider({
  children,
  t = createTranslator(),
  locale = "en",
  ...value
}: Omit<PortalContextValue, "t" | "locale"> & { t?: Translate; locale?: string; children: ReactNode }) {
  return <PortalContext.Provider value={{ ...value, t, locale }}>{children}</PortalContext.Provider>;
}

export function usePortal() {
  const value = useContext(PortalContext);
  if (!value) throw new Error("Wrap customer support screens in <SupportPortalProvider>.");
  return value;
}

export const toDate = (value: DateLike) => (value instanceof Date ? value : new Date(value));

import type { DateLike, Identity } from "./client";

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

// Latin digits in Arabic: that's what most Arabic-speaking product UIs show for times and amounts.
const intlLocale = (locale: string) => (locale.startsWith("ar") ? `${locale}-u-nu-latn` : locale);

const toDate = (value: DateLike) => (value instanceof Date ? value : new Date(value));

/** "12 min", "3 h", "2 days": how long someone has been waiting. */
export function formatDuration(from: DateLike, locale: string, now = Date.now()) {
  const ms = Math.max(0, now - toDate(from).getTime());
  const format = (value: number, unit: "minute" | "hour" | "day") =>
    new Intl.NumberFormat(intlLocale(locale), { style: "unit", unit, unitDisplay: "short" }).format(value);
  if (ms < HOUR) return format(Math.max(1, Math.floor(ms / MINUTE)), "minute");
  if (ms < DAY) return format(Math.floor(ms / HOUR), "hour");
  return format(Math.floor(ms / DAY), "day");
}

/** "09:31" today, "Oct 18" this year, "Oct 18, 2025" before. */
export function formatWhen(value: DateLike, locale: string, now = new Date()) {
  const date = toDate(value);
  const l = intlLocale(locale);
  if (date.toDateString() === now.toDateString()) {
    return date.toLocaleTimeString(l, { hour: "2-digit", minute: "2-digit", hour12: false });
  }
  return date.toLocaleDateString(l, {
    day: "numeric",
    month: "short",
    ...(date.getFullYear() === now.getFullYear() ? {} : { year: "numeric" }),
  });
}

/** "Oct 18, 09:31": the full timestamp on a message. */
export function formatTimestamp(value: DateLike, locale: string) {
  return toDate(value).toLocaleString(intlLocale(locale), {
    day: "numeric",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
}

/** How urgent a wait is against the response target: amber from 75%, red past it. */
export function waitLevel(since: DateLike, targetMinutes: number, now = Date.now()): "normal" | "soon" | "late" {
  const ratio = (now - toDate(since).getTime()) / (targetMinutes * MINUTE);
  return ratio >= 1 ? "late" : ratio >= 0.75 ? "soon" : "normal";
}

export function formatBytes(bytes: number, locale: string) {
  const units = ["byte", "kilobyte", "megabyte"] as const;
  let value = bytes;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit++;
  }
  return new Intl.NumberFormat(intlLocale(locale), {
    style: "unit",
    unit: units[unit],
    unitDisplay: "short",
    maximumFractionDigits: unit ? 1 : 0,
  }).format(value);
}

/** The best way to show who a contact is: their name, else their email or number. */
export function contactLabel(contact: { name: string | null; identities: Identity[] }) {
  return contact.name || contact.identities[0]?.value || "";
}

export function initials(name: string) {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  return ((parts[0]?.[0] ?? "") + (parts.length > 1 ? parts.at(-1)![0] : "")).toUpperCase() || "?";
}

"use client";

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import DOMPurify from "dompurify";
import { Paperclip } from "lucide-react";
import { cn } from "@/lib/utils";
import type { FileInfo, TicketStatus } from "./client";
import { formatBytes, initials } from "./format";
import { useSupport } from "./provider";

export function AgentAvatar({ name, className }: { name: string; className?: string }) {
  return (
    <span
      className={cn(
        "inline-flex size-6 shrink-0 items-center justify-center rounded-full bg-primary/10 text-[10px] font-semibold text-primary",
        className
      )}
      aria-hidden
    >
      {initials(name)}
    </span>
  );
}

const statusStyles: Record<TicketStatus, string> = {
  open: "bg-blue-50 text-blue-700 ring-blue-600/20 dark:bg-blue-500/10 dark:text-blue-300",
  waiting: "bg-amber-50 text-amber-800 ring-amber-600/20 dark:bg-amber-500/10 dark:text-amber-300",
  solved: "bg-emerald-50 text-emerald-700 ring-emerald-600/20 dark:bg-emerald-500/10 dark:text-emerald-300",
  spam: "bg-slate-100 text-slate-600 ring-slate-500/20 dark:bg-slate-500/10 dark:text-slate-300",
};

export function StatusBadge({ status, label }: { status: TicketStatus; label: string }) {
  return (
    <span className={cn("inline-flex items-center rounded-md px-1.5 py-0.5 text-xs font-medium ring-1 ring-inset", statusStyles[status])}>
      {label}
    </span>
  );
}

export function UnknownSenderBadge() {
  const { t } = useSupport();
  return (
    <span className="inline-flex shrink-0 items-center rounded-md bg-amber-50 px-1.5 py-0.5 text-[11px] font-medium text-amber-800 ring-1 ring-inset ring-amber-600/20 dark:bg-amber-500/10 dark:text-amber-300">
      {t("inbox.unknownSender")}
    </span>
  );
}

/** A file on a message. Downloads through a short-lived signed URL fetched on click. */
export function AttachmentChip({ file, getUrl, locale }: { file: FileInfo; getUrl: () => Promise<string>; locale: string }) {
  const [busy, setBusy] = useState(false);
  return (
    <button
      type="button"
      disabled={busy}
      onClick={async () => {
        setBusy(true);
        try {
          window.open(await getUrl(), "_blank", "noopener,noreferrer");
        } finally {
          setBusy(false);
        }
      }}
      className="inline-flex max-w-full items-center gap-1.5 rounded-md border bg-background px-2 py-1 text-xs text-muted-foreground transition-colors hover:text-foreground disabled:opacity-60"
    >
      <Paperclip className="size-3.5 shrink-0" />
      <bdi className="truncate">{file.filename}</bdi>
      <span className="shrink-0 tabular-nums">{formatBytes(file.size, locale)}</span>
    </button>
  );
}

/** Plain text with links made clickable, paragraph by paragraph so mixed Arabic and Latin text lines up. */
export function MessageText({ text, className }: { text: string; className?: string }) {
  const paragraphs = text.split(/\n{2,}/);
  return (
    <div className={cn("space-y-3 text-sm leading-relaxed break-words", className)}>
      {paragraphs.map((paragraph, i) => (
        <p key={i} dir="auto" className="whitespace-pre-wrap">
          {linkify(paragraph)}
        </p>
      ))}
    </div>
  );
}

function linkify(text: string): ReactNode[] {
  return text.split(/(https?:\/\/[^\s<>"]+)/g).map((part, i) =>
    i % 2 ? (
      <a key={i} href={part} target="_blank" rel="noopener noreferrer nofollow" className="underline underline-offset-2">
        {part}
      </a>
    ) : (
      part
    )
  );
}

/**
 * The original email exactly as sent, isolated: sanitized with DOMPurify, rendered in a sandboxed
 * iframe that can't run scripts, with remote images blocked until the agent asks for them
 * (they are often tracking pixels).
 */
export function EmailFrame({ html, showImagesLabel }: { html: string; showImagesLabel: string }) {
  const [images, setImages] = useState(false);
  const [height, setHeight] = useState(200);
  const ref = useRef<HTMLIFrameElement>(null);
  const hasRemoteImages = /<img[^>]+src=["']?https?:/i.test(html);

  const srcDoc = useMemo(() => {
    const clean = DOMPurify.sanitize(html, {
      WHOLE_DOCUMENT: false,
      FORBID_TAGS: ["style", "form", "input", "button", "textarea", "select", "iframe", "object", "embed"],
      FORBID_ATTR: ["style"],
    });
    const csp = `default-src 'none'; img-src data: cid:${images ? " https: http:" : ""}; style-src 'unsafe-inline'; font-src data:`;
    return `<!doctype html><html><head><meta http-equiv="Content-Security-Policy" content="${csp}"><base target="_blank"><style>body{margin:0;font:14px/1.6 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:#111;word-break:break-word}img{max-width:100%;height:auto}blockquote{margin:0 0 0 .5em;padding-inline-start:.75em;border-inline-start:2px solid #ddd;color:#555}</style></head><body dir="auto">${clean}</body></html>`;
  }, [html, images]);

  useEffect(() => {
    const frame = ref.current;
    if (!frame) return;
    // allow-same-origin is required to read the height; scripts stay disabled, so the content can't use it.
    const measure = () => setHeight(Math.min(1600, (frame.contentDocument?.body?.scrollHeight ?? 200) + 8));
    frame.addEventListener("load", measure);
    return () => frame.removeEventListener("load", measure);
  }, [srcDoc]);

  return (
    <div className="space-y-2">
      {hasRemoteImages && !images && (
        <button type="button" onClick={() => setImages(true)} className="text-xs text-muted-foreground underline underline-offset-2 hover:text-foreground">
          {showImagesLabel}
        </button>
      )}
      <iframe
        ref={ref}
        title="email"
        sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox"
        srcDoc={srcDoc}
        style={{ height }}
        className="w-full rounded-md border bg-white"
      />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { keepPreviousData, useQuery } from "@tanstack/react-query";
import { ChevronLeft, ChevronRight, Search, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Select, SelectContent, SelectItem, SelectSeparator, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useSupport } from "./provider";
import type { TicketListItem, TicketStatus } from "./client";
import { contactLabel, formatDuration, formatWhen, waitLevel } from "./format";
import { AgentAvatar, UnknownSenderBadge } from "./parts";
import { UrgencyMark } from "./ai";

const TABS: TicketStatus[] = ["open", "waiting", "solved"];
const PAGE_SIZE = 25;

/** The shared inbox: what needs an answer, longest wait first. With AI, the most urgent come before that. */
export function SupportInbox() {
  const { client, t, viewerId } = useSupport();
  const router = useRouter();
  const pathname = usePathname();
  const params = useSearchParams();
  const status = (["open", "waiting", "solved", "spam"].includes(params.get("status") ?? "") ? params.get("status") : "open") as TicketStatus;
  const assignee = params.get("assignee") ?? "any";
  const page = Math.max(1, Number(params.get("page")) || 1);
  const search = params.get("q") ?? "";
  const [draft, setDraft] = useState(search);

  const setParams = (updates: Record<string, string | null>) => {
    const next = new URLSearchParams(params);
    for (const [key, value] of Object.entries(updates)) {
      if (value) next.set(key, value);
      else next.delete(key);
    }
    if (!("page" in updates)) next.delete("page");
    router.replace(`${pathname}${next.size ? `?${next}` : ""}`, { scroll: false });
  };

  useEffect(() => setDraft(search), [search]);
  useEffect(() => {
    if (draft === search) return;
    const timer = setTimeout(() => setParams({ q: draft.trim() || null }), 350);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft]);

  const counts = useQuery({ queryKey: ["support", "counts"], queryFn: () => client.counts(), refetchInterval: 30_000 });
  const agents = useQuery({ queryKey: ["support", "agents"], queryFn: () => client.listAgents(), staleTime: 5 * 60_000 });
  const assigneeLabel =
    assignee === "any"
      ? t("inbox.anyone")
      : assignee === "me"
        ? t("inbox.me")
        : assignee === "none"
          ? t("inbox.unassigned")
          : (agents.data?.find((a) => a.id === assignee)?.name ?? t("inbox.anyone"));
  const sort = client.ai && status === "open" ? ("priority" as const) : undefined;
  const list = useQuery({
    queryKey: ["support", "tickets", { status, assignee, page, search, sort }],
    queryFn: () =>
      client.listTickets({
        status,
        assignee: assignee === "any" ? undefined : assignee === "none" ? null : assignee,
        search: search || undefined,
        ...(sort ? { sort } : {}),
        page,
        pageSize: PAGE_SIZE,
      }),
    placeholderData: keepPreviousData,
    refetchInterval: 20_000,
  });

  const tabs = counts.data?.spam || status === "spam" ? [...TABS, "spam" as const] : TABS;
  const total = list.data?.total ?? 0;
  const from = total ? (page - 1) * PAGE_SIZE + 1 : 0;
  const to = Math.min(page * PAGE_SIZE, total);

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-end justify-between gap-3 border-b">
        <div className="-mb-px flex gap-1 overflow-x-auto">
          {tabs.map((tab) => (
            <button
              key={tab}
              type="button"
              onClick={() => setParams({ status: tab === "open" ? null : tab })}
              className={cn(
                "shrink-0 border-b-2 px-3 pb-2.5 text-sm font-medium transition-colors",
                tab === status ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"
              )}
            >
              {t(`status.${tab}`)}
              {tab !== "solved" && counts.data?.[tab] ? (
                <span className="ms-1.5 tabular-nums text-xs text-muted-foreground">{counts.data[tab]}</span>
              ) : null}
            </button>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2 pb-2">
          <div className="relative">
            <Search className="pointer-events-none absolute start-2.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              placeholder={t("inbox.search")}
              className="h-9 w-56 ps-8"
              aria-label={t("inbox.search")}
            />
          </div>
          {/* Works with Radix and Base UI selects: the label is rendered here, and an empty value means "anyone". */}
          <Select value={assignee} onValueChange={(value) => setParams({ assignee: !value || value === "any" ? null : String(value) })}>
            <SelectTrigger className="h-9 w-44" aria-label={t("inbox.assignee")}>
              <SelectValue>{assigneeLabel}</SelectValue>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="any">{t("inbox.anyone")}</SelectItem>
              <SelectItem value="me">{t("inbox.me")}</SelectItem>
              <SelectItem value="none">{t("inbox.unassigned")}</SelectItem>
              {agents.data?.some((a) => a.id !== viewerId) && <SelectSeparator />}
              {agents.data
                ?.filter((a) => a.id !== viewerId)
                .map((agent) => (
                  <SelectItem key={agent.id} value={agent.id}>
                    {agent.name}
                  </SelectItem>
                ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {list.error ? (
        <div className="rounded-xl border bg-card px-4 py-12 text-center">
          <p className="text-sm text-destructive">{t("errors.load")}</p>
          <Button variant="outline" size="sm" className="mt-3" onClick={() => list.refetch()}>
            {t("actions.retry")}
          </Button>
        </div>
      ) : (
        <div className="overflow-hidden rounded-xl border bg-card">
          <div className="hidden grid-cols-[8px_minmax(0,13rem)_minmax(0,1fr)_9rem_6rem] gap-4 border-b bg-muted/40 px-4 py-2 text-xs font-medium text-muted-foreground md:grid">
            <span />
            <span>{t("inbox.columns.customer")}</span>
            <span>{t("inbox.columns.subject")}</span>
            <span>{t("inbox.columns.assignee")}</span>
            <span className="text-end">{t(status === "open" ? "inbox.columns.waiting" : status === "solved" ? "inbox.columns.solved" : "inbox.columns.updated")}</span>
          </div>
          {list.isPending ? (
            <div className="divide-y">
              {Array.from({ length: 6 }, (_, i) => (
                <div key={i} className="flex gap-4 px-4 py-3.5">
                  <Skeleton className="h-4 w-40" />
                  <Skeleton className="h-4 flex-1" />
                </div>
              ))}
            </div>
          ) : list.data?.items.length ? (
            <ul className="divide-y">
              {list.data.items.map((ticket) => (
                <TicketRow key={ticket.id} ticket={ticket} status={status} agents={agents.data ?? []} />
              ))}
            </ul>
          ) : (
            <p className="px-4 py-16 text-center text-sm text-muted-foreground">
              {search ? t("inbox.empty.search") : t(`inbox.empty.${status}`)}
            </p>
          )}
        </div>
      )}

      {total > PAGE_SIZE && (
        <div className="flex items-center justify-end gap-2 text-sm text-muted-foreground">
          <span className="tabular-nums">{t("inbox.range", { from, to, total })}</span>
          <Button variant="outline" size="icon" className="size-8" disabled={page <= 1} onClick={() => setParams({ page: String(page - 1) })} aria-label={t("actions.previous")}>
            <ChevronLeft className="size-4 rtl:rotate-180" />
          </Button>
          <Button variant="outline" size="icon" className="size-8" disabled={to >= total} onClick={() => setParams({ page: String(page + 1) })} aria-label={t("actions.next")}>
            <ChevronRight className="size-4 rtl:rotate-180" />
          </Button>
        </div>
      )}
    </div>
  );
}

function TicketRow({ ticket, status, agents }: { ticket: TicketListItem; status: TicketStatus; agents: { id: string; name: string }[] }) {
  const { t, locale, ticketHref, responseTargetMinutes, viewerId } = useSupport();
  const who = contactLabel(ticket.contact);
  const previewAuthor =
    ticket.previewKind === "outbound"
      ? ticket.previewAuthorId === viewerId
        ? t("inbox.you")
        : agents.find((a) => a.id === ticket.previewAuthorId)?.name.split(" ")[0]
      : null;
  const level = ticket.waitingSince ? waitLevel(ticket.waitingSince, responseTargetMinutes) : "normal";
  // Once your team has answered, their reply says more than a summary of the question.
  const summary = ticket.previewKind !== "outbound" ? ticket.summary : null;

  return (
    <li>
      <Link
        href={ticketHref(ticket.id)}
        className="grid grid-cols-[8px_minmax(0,1fr)_auto] items-center gap-x-4 gap-y-1 px-4 py-3 transition-colors hover:bg-muted/50 md:grid-cols-[8px_minmax(0,13rem)_minmax(0,1fr)_9rem_6rem]"
      >
        <span className={cn("size-2 rounded-full", ticket.unread ? "bg-primary" : "bg-transparent")} aria-label={ticket.unread ? t("inbox.unread") : undefined} />
        <div className="min-w-0">
          <p className={cn("truncate text-sm", ticket.unread ? "font-semibold" : "font-medium")}>
            <bdi>{ticket.customer?.name ?? who}</bdi>
          </p>
          <div className="flex min-w-0 items-center gap-1.5">
            {ticket.customer ? (
              <p className="truncate text-xs text-muted-foreground">
                <bdi>{who}</bdi>
              </p>
            ) : (
              <UnknownSenderBadge />
            )}
          </div>
        </div>
        <div className="col-span-2 col-start-2 min-w-0 md:col-span-1 md:col-start-3 md:row-start-1">
          <div className="flex min-w-0 items-center gap-1.5">
            <p dir="auto" className={cn("truncate text-sm", ticket.unread ? "font-semibold" : "font-medium")}>
              {ticket.subject || t("inbox.noSubject")}
            </p>
            {ticket.draftReady && (
              <span className="shrink-0 text-primary" title={t("ai.draftReady")}>
                <Sparkles className="size-3.5" aria-label={t("ai.draftReady")} />
              </span>
            )}
          </div>
          {/* What the customer needs, when AI has read their message; else the message itself. */}
          <div className="flex min-w-0 items-center gap-1.5">
            {status === "open" && <UrgencyMark urgency={ticket.urgency} />}
            {summary ? (
              <p dir="auto" className="truncate text-sm text-muted-foreground">
                {summary}
              </p>
            ) : (
              ticket.preview && (
                <p dir="auto" className="truncate text-sm text-muted-foreground">
                  {previewAuthor && <span className="text-foreground/70">{previewAuthor}: </span>}
                  {ticket.preview}
                </p>
              )
            )}
          </div>
        </div>
        <div className="hidden min-w-0 items-center gap-2 text-sm text-muted-foreground md:col-start-4 md:row-start-1 md:flex">
          {ticket.assignee ? (
            <>
              <AgentAvatar name={ticket.assignee.name} />
              <span className="truncate">{ticket.assignee.id === viewerId ? t("inbox.you") : ticket.assignee.name.split(" ")[0]}</span>
            </>
          ) : (
            <span>{t("inbox.unassigned")}</span>
          )}
        </div>
        <div
          className={cn(
            "col-start-3 row-start-1 text-end text-xs tabular-nums whitespace-nowrap md:col-start-5 md:text-sm",
            level === "late" ? "font-semibold text-red-600 dark:text-red-400" : level === "soon" ? "font-semibold text-amber-600 dark:text-amber-400" : "text-muted-foreground"
          )}
        >
          {status === "open" && ticket.waitingSince ? formatDuration(ticket.waitingSince, locale) : formatWhen(ticket.lastMessageAt, locale)}
        </div>
      </Link>
    </li>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertCircle, ArrowLeft, Ban, Link2, MoreHorizontal, RotateCw, UserPen } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { buttonVariants } from "@/components/ui/button";
import { useSupport } from "./provider";
import type { Agent, TicketDetail, TicketStatus, TimelineEvent, TimelineMessage } from "./client";
import { contactLabel, formatTimestamp, formatWhen } from "./format";
import { AgentAvatar, AttachmentChip, EmailFrame, MessageText, StatusBadge, UnknownSenderBadge } from "./parts";
import { SupportComposer } from "./support-composer";
import { LinkCustomerDialog } from "./link-customer-dialog";
import { ChangeContactDialog } from "./change-contact-dialog";
import { TicketInsightBar, foreignLanguage, languageName, useMessageTranslation } from "./ai";

/** One ticket: the conversation, the reply box, and the customer next to it. */
export function SupportTicket({ ticketId }: { ticketId: string }) {
  const { client, t, inboxHref } = useSupport();
  const ticket = useQuery({
    queryKey: ["support", "ticket", ticketId],
    queryFn: () => client.getTicket(ticketId),
    refetchInterval: 15_000,
  });
  const agents = useQuery({ queryKey: ["support", "agents"], queryFn: () => client.listAgents(), staleTime: 5 * 60_000 });

  if (ticket.error) {
    return (
      <div className="rounded-xl border bg-card px-4 py-12 text-center">
        <p className="text-sm text-destructive">{t("errors.load")}</p>
        <Button variant="outline" size="sm" className="mt-3" onClick={() => ticket.refetch()}>
          {t("actions.retry")}
        </Button>
      </div>
    );
  }
  if (!ticket.data) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-8 w-80" />
        <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_18rem]">
          <Skeleton className="h-96" />
          <Skeleton className="h-64" />
        </div>
      </div>
    );
  }

  const detail = ticket.data;
  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0">
          <Link href={inboxHref} className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground">
            <ArrowLeft className="size-4 rtl:rotate-180" />
            {t("ticket.back")}
          </Link>
          <h1 dir="auto" className="mt-1 text-2xl font-semibold tracking-tight break-words">
            {detail.ticket.subject || t("inbox.noSubject")}
          </h1>
          <TicketInsightBar detail={detail} />
        </div>
        <TicketControls detail={detail} agents={agents.data ?? []} />
      </div>

      <div className="grid items-start gap-6 lg:grid-cols-[minmax(0,1fr)_18rem]">
        <div className="space-y-3">
          <Timeline detail={detail} agents={agents.data ?? []} />
          {detail.ticket.status === "spam" ? (
            <p className="rounded-lg border border-dashed px-4 py-3 text-sm text-muted-foreground">{t("ticket.spamNotice")}</p>
          ) : (
            <SupportComposer detail={detail} />
          )}
        </div>
        <CustomerSidebar detail={detail} />
      </div>
    </div>
  );
}

function useTicketMutation<T>(ticketId: string, fn: (input: T) => Promise<unknown>) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: fn,
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["support", "ticket", ticketId] });
      queryClient.invalidateQueries({ queryKey: ["support", "tickets"] });
      queryClient.invalidateQueries({ queryKey: ["support", "counts"] });
    },
  });
}

function TicketControls({ detail, agents }: { detail: TicketDetail; agents: Agent[] }) {
  const { client, t, viewerId } = useSupport();
  const id = detail.ticket.id;
  const setStatus = useTicketMutation(id, (status: TicketStatus) => client.setStatus({ ticketId: id, status }));
  const assign = useTicketMutation(id, (assigneeId: string | null) => client.assign({ ticketId: id, assigneeId }));
  const [linking, setLinking] = useState(false);
  const [changingContact, setChangingContact] = useState(false);
  // Controlled, so picking an option closes the menu with Radix and Base UI alike.
  const [statusOpen, setStatusOpen] = useState(false);
  const [assignOpen, setAssignOpen] = useState(false);
  const assigneeName = detail.assignee ? (detail.assignee.id === viewerId ? t("inbox.you") : detail.assignee.name) : t("inbox.unassigned");
  const trigger = buttonVariants({ variant: "outline", size: "sm" });

  return (
    <div className="flex flex-wrap items-center gap-2">
      {detail.ticket.status !== "spam" && (
        <DropdownMenu open={statusOpen} onOpenChange={setStatusOpen}>
          <DropdownMenuTrigger className={trigger} disabled={setStatus.isPending}>
            <span className="text-muted-foreground">{t("ticket.statusLabel")}</span>
            <span>{t(`status.${detail.ticket.status}`)}</span>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-auto min-w-44">
            <DropdownMenuRadioGroup
              value={detail.ticket.status}
              onValueChange={(v) => {
                setStatusOpen(false);
                setStatus.mutate(v as TicketStatus);
              }}
            >
              {(["open", "waiting", "solved"] as const).map((status) => (
                <DropdownMenuRadioItem key={status} value={status}>
                  {t(`status.${status}`)}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>
      )}

      <DropdownMenu open={assignOpen} onOpenChange={setAssignOpen}>
        <DropdownMenuTrigger className={trigger} disabled={assign.isPending}>
          <span className="text-muted-foreground">{t("ticket.assigneeLabel")}</span>
          <span>{assigneeName}</span>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="max-h-80 w-auto min-w-44 overflow-y-auto">
          <DropdownMenuRadioGroup
            value={detail.ticket.assigneeId ?? ""}
            onValueChange={(v) => {
              setAssignOpen(false);
              assign.mutate(v || null);
            }}
          >
            <DropdownMenuRadioItem value={viewerId}>{t("ticket.assignToMe")}</DropdownMenuRadioItem>
            {agents
              .filter((a) => a.id !== viewerId)
              .map((agent) => (
                <DropdownMenuRadioItem key={agent.id} value={agent.id}>
                  {agent.name}
                </DropdownMenuRadioItem>
              ))}
            <DropdownMenuSeparator />
            <DropdownMenuRadioItem value="">{t("inbox.unassigned")}</DropdownMenuRadioItem>
          </DropdownMenuRadioGroup>
        </DropdownMenuContent>
      </DropdownMenu>

      <DropdownMenu>
        <DropdownMenuTrigger className={buttonVariants({ variant: "outline", size: "icon" }) + " size-8"} aria-label={t("ticket.more")}>
          <MoreHorizontal className="size-4" />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-auto min-w-44">
          <DropdownMenuItem onClick={() => setLinking(true)}>
            <Link2 className="size-4" />
            {detail.customer ? t("ticket.changeCustomer") : t("ticket.linkCustomer")}
          </DropdownMenuItem>
          <DropdownMenuItem onClick={() => setChangingContact(true)}>
            <UserPen className="size-4" />
            {t("ticket.changeContact")}
          </DropdownMenuItem>
          {detail.ticket.status === "spam" ? (
            <DropdownMenuItem onClick={() => setStatus.mutate("open")}>
              <RotateCw className="size-4" />
              {t("ticket.notSpam")}
            </DropdownMenuItem>
          ) : (
            <DropdownMenuItem className="text-destructive focus:text-destructive" onClick={() => setStatus.mutate("spam")}>
              <Ban className="size-4" />
              {t("ticket.markSpam")}
            </DropdownMenuItem>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
      <LinkCustomerDialog detail={detail} open={linking} onOpenChange={setLinking} />
      <ChangeContactDialog detail={detail} open={changingContact} onOpenChange={setChangingContact} />
    </div>
  );
}

function Timeline({ detail, agents }: { detail: TicketDetail; agents: Agent[] }) {
  const { t, locale, viewerId } = useSupport();
  const agentName = (id: string | null) =>
    !id ? null : id === viewerId ? t("inbox.you") : agents.find((a) => a.id === id)?.name ?? t("ticket.formerAgent");

  // A reply already says who took the ticket and that it now waits on the customer; don't repeat it.
  const replies = detail.timeline.flatMap((e) =>
    e.type === "message" && e.message.kind === "outbound" && e.message.authorId ? [e.message] : []
  );
  const impliedByReply = (event: TimelineEvent) => {
    const selfAssigned = event.type === "assigned" && event.data.to === event.actorId;
    const nowWaiting = event.type === "status_changed" && event.data.to === "waiting";
    return (
      (selfAssigned || nowWaiting) &&
      replies.some(
        (m) => m.authorId === event.actorId && Math.abs(new Date(m.createdAt).getTime() - new Date(event.createdAt).getTime()) < 10_000
      )
    );
  };

  return (
    <ol className="space-y-3">
      {detail.timeline.filter((entry) => entry.type === "message" || !impliedByReply(entry.event)).map((entry) =>
        entry.type === "message" ? (
          <li key={entry.message.id}>
            <MessageCard message={entry.message} detail={detail} agents={agents} agentName={agentName} />
          </li>
        ) : (
          <li key={entry.event.id} className="px-2 py-1 text-center text-xs text-muted-foreground">
            {describeEvent(entry.event, t, agentName)} · {formatWhen(entry.event.createdAt, locale)}
          </li>
        )
      )}
    </ol>
  );
}

function describeEvent(event: TimelineEvent, t: ReturnType<typeof useSupport>["t"], agentName: (id: string | null) => string | null) {
  const actor = agentName(event.actorId) ?? t("ticket.events.system");
  switch (event.type) {
    case "assigned": {
      const to = event.data.to as string | null;
      if (!to) return t("ticket.events.unassigned", { actor });
      if (to === event.actorId) return t("ticket.events.took", { actor });
      return t("ticket.events.assigned", { actor, assignee: agentName(to) ?? "" });
    }
    case "status_changed":
      return t("ticket.events.status", { actor, status: t(`status.${event.data.to as TicketStatus}`) });
    case "customer_linked":
      return event.data.to ? t("ticket.events.linked", { actor }) : t("ticket.events.unlinked", { actor });
    case "reopened":
      return t("ticket.events.reopened");
    case "follow_up":
      return t("ticket.events.followUp", { number: String(event.data.number) });
    case "contact_changed":
      return t("ticket.events.contactChanged", { actor, address: String(event.data.address ?? "") });
    case "insight_changed": {
      const urgency = (event.data.urgency as { to?: string } | undefined)?.to;
      const topic = (event.data.topic as { to?: string } | undefined)?.to;
      if (urgency) return t("ticket.events.urgencyChanged", { actor, urgency: t(`ai.urgency.${urgency}`) });
      return t("ticket.events.topicChanged", { actor, topic: !topic || topic === "other" ? t("ai.otherTopic") : topic });
    }
    case "forwarded": {
      const from = event.data.from as { address: string; name?: string | null } | undefined;
      return t("ticket.events.forwarded", { actor: agentName(event.actorId) ?? from?.name ?? from?.address ?? actor });
    }
    default:
      return event.type;
  }
}

function MessageCard({
  message,
  detail,
  agents,
  agentName,
}: {
  message: TimelineMessage;
  detail: TicketDetail;
  agents: Agent[];
  agentName: (id: string | null) => string | null;
}) {
  const { client, t, locale } = useSupport();
  const [original, setOriginal] = useState(false);
  const retry = useTicketMutation(detail.ticket.id, () => client.retry({ messageId: message.id }));
  const translation = useMessageTranslation(message.id);

  if (message.auto && message.kind === "outbound") {
    return <p className="px-2 py-1 text-center text-xs text-muted-foreground">{t("ticket.autoReplySent")} · {formatWhen(message.createdAt, locale)}</p>;
  }

  const author =
    message.kind === "inbound"
      ? message.from?.name || message.from?.address || contactLabel(detail.contact)
      : agentName(message.authorId) ?? message.from?.name ?? t("ticket.formerAgent");
  // Initials come from the real name even when the label says "You".
  const avatarName =
    message.kind === "inbound" ? author : agents.find((a) => a.id === message.authorId)?.name ?? author;
  // Only offer the full message when it shows something more: quoted history, or layout and images.
  const hasMore =
    message.kind === "inbound" &&
    ((message.fullText !== null && message.fullText.trim() !== message.text.trim()) ||
      (message.html !== null && /<(table|img)\b/i.test(message.html)));
  const failed = message.deliveryStatus === "failed";
  // Offered only when the customer writes in another language than the agent reads.
  const foreign = client.ai && message.kind === "inbound" ? foreignLanguage(detail, locale) : null;

  return (
    <article
      className={cn(
        "rounded-xl border p-4",
        message.kind === "note" && "border-amber-300/60 bg-amber-50 dark:border-amber-500/30 dark:bg-amber-500/10",
        message.kind === "outbound" && "border-primary/20 bg-primary/[0.03]",
        message.kind === "inbound" && "bg-card",
        failed && "border-destructive/40"
      )}
    >
      <header className="mb-2 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-muted-foreground">
        <AgentAvatar name={avatarName} className={message.kind === "inbound" ? "bg-muted text-foreground/70" : undefined} />
        <bdi className="text-sm font-medium text-foreground">{author}</bdi>
        {message.kind === "note" && <span className="font-medium text-amber-700 dark:text-amber-300">{t("ticket.note")}</span>}
        {message.kind === "inbound" && message.from && message.from.name && <bdi dir="ltr">{message.from.address}</bdi>}
        {message.source === "portal" && <span>{t("ticket.viaPortal")}</span>}
        <time className="ms-auto tabular-nums" dateTime={new Date(message.createdAt).toISOString()}>
          {formatTimestamp(message.createdAt, locale)}
        </time>
      </header>

      {translation.text !== null ? (
        <MessageText text={translation.text} />
      ) : original && message.html ? (
        <EmailFrame html={message.html} showImagesLabel={t("ticket.showImages")} />
      ) : (
        <MessageText text={original && message.fullText ? message.fullText : message.text} />
      )}

      {message.attachments.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-2">
          {message.attachments.map((file) => (
            <AttachmentChip key={file.id} file={file} locale={locale} getUrl={() => client.attachmentUrl({ id: file.id })} />
          ))}
        </div>
      )}

      {(hasMore || failed || foreign) && (
        <footer className="mt-3 flex flex-wrap items-center gap-3 text-xs">
          {foreign && (
            <span className="inline-flex items-center gap-2 text-muted-foreground">
              {translation.text !== null && <span>{t("ai.translatedFrom", { language: languageName(foreign, locale) })}</span>}
              <button type="button" className="underline underline-offset-2 hover:text-foreground disabled:opacity-60" disabled={translation.pending} onClick={translation.toggle}>
                {translation.text !== null ? t("ai.showUntranslated") : t("ai.translate")}
              </button>
              {translation.failed && <span className="text-destructive">{t("ai.failed")}</span>}
            </span>
          )}
          {hasMore && translation.text === null && (
            <button type="button" className="text-muted-foreground underline underline-offset-2 hover:text-foreground" onClick={() => setOriginal((v) => !v)}>
              {original ? t("ticket.showReply") : t("ticket.showOriginal")}
            </button>
          )}
          {failed && (
            <span className="inline-flex flex-wrap items-center gap-2 text-destructive">
              <AlertCircle className="size-3.5" />
              {t("ticket.notDelivered")}
              {message.deliveryError && <span className="text-muted-foreground">{message.deliveryError}</span>}
              <Button variant="outline" size="sm" className="h-7" disabled={retry.isPending} onClick={() => retry.mutate(undefined)}>
                {t("actions.retry")}
              </Button>
            </span>
          )}
        </footer>
      )}
    </article>
  );
}

